package com.primehr.rewardsrecognition.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;
@Entity @Table(name="rr_eligibility_finding",uniqueConstraints=@UniqueConstraint(name="uk_rr_eligibility_rule",columnNames={"agency_id","evaluation_case_id","normalized_rule_code"}))
public class RrEligibilityFinding extends RspAuditedEntity{public enum Outcome{PASS,FAIL,NOT_APPLICABLE}@Column(name="evaluation_case_id",nullable=false,length=36)private String evaluationCaseId;@Column(name="rule_code",nullable=false,length=100)private String ruleCode;@Column(name="normalized_rule_code",nullable=false,length=100)private String normalizedRuleCode;@Column(name="rule_label",nullable=false,length=300)private String ruleLabel;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private Outcome outcome;@Column(nullable=false,length=3000)private String rationale;protected RrEligibilityFinding(){}public RrEligibilityFinding(String a,String c,String code,String label,Outcome o,String rationale){super(a);evaluationCaseId=requiredText(c,"evaluationCaseId");ruleCode=requiredText(code,"ruleCode");normalizedRuleCode=ruleCode.toUpperCase(java.util.Locale.ROOT);ruleLabel=requiredText(label,"ruleLabel");outcome=java.util.Objects.requireNonNull(o,"outcome");this.rationale=requiredText(rationale,"rationale");}public String getEvaluationCaseId(){return evaluationCaseId;}public String getRuleCode(){return ruleCode;}public String getRuleLabel(){return ruleLabel;}public Outcome getOutcome(){return outcome;}public String getRationale(){return rationale;}}
